17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
33	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
34	import org.springframework.samples.petclinic.rest.validation.CityOwnerLimitException;
35	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitException;
36	import org.springframework.samples.petclinic.rest.validation.DisposableEmailDomainException;
37	import org.springframework.samples.petclinic.rest.validation.DuplicateIdentityException;
38	import org.springframework.samples.petclinic.rest.validation.FutureRegistrationDateException;
39	import org.springframework.samples.petclinic.rest.validation.HouseholdDuplicateException;
40	import org.springframework.samples.petclinic.rest.validation.InvalidEmailException;
41	import org.springframework.samples.petclinic.rest.validation.InvalidPostcodeException;
42	import org.springframework.samples.petclinic.rest.validation.InvalidTelephoneException;
43	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
44	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
45	import org.springframework.samples.petclinic.rest.validation.ValidationErrorsResponse;
46	import org.springframework.security.access.AccessDeniedException;
47	import org.springframework.validation.BindingResult;
48	import org.springframework.web.bind.MethodArgumentNotValidException;
49	import org.springframework.web.bind.annotation.ControllerAdvice;
50	import org.springframework.web.bind.annotation.ExceptionHandler;
51	import org.springframework.web.bind.annotation.ResponseBody;
52	
53	/**
54	 * Global Exception handler for REST controllers.
55	 * <p>
56	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
57	 *
58	 * @author Vitaliy Fedoriv
59	 * @author Alexander Dudkin
60	 */
61	@ControllerAdvice
62	public class ExceptionControllerAdvice {
63	
64	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
65	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
66	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
67	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
68	
69	    private final OwnerFieldsValidator ownerFieldsValidator;
70	
71	    public ExceptionControllerAdvice(OwnerFieldsValidator ownerFieldsValidator) {
72	        this.ownerFieldsValidator = ownerFieldsValidator;
73	    }
74	
75	    /**
76	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
77	     * class.
78	     *
79	     * @param e     Object referring to the thrown exception.
80	     * @param status HTTP response status.
81	     * @param url URL request.
82	     */
83	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
84	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
85	        problemDetail.setType(URI.create(url.toString()));
86	        problemDetail.setTitle(e.getClass().getSimpleName());
87	        problemDetail.setDetail(detail);
88	        problemDetail.setProperty("timestamp", Instant.now());
89	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
90	        return problemDetail;
91	    }
92	
93	    /**
94	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
95	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
96	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
97	     * would catch it and report an authorization failure as a 500.
98	     *
99	     * @param e The {@link AccessDeniedException} to propagate
100	     * @throws AccessDeniedException always
101	     */
102	    @ExceptionHandler(AccessDeniedException.class)
103	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
104	        throw e;
105	    }
106	
107	    /**
108	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
109	     *
110	     * @param e The {@link Exception} to be handled
111	     * @param request {@link HttpServletRequest} object referring to the current request.
112	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
113	     */
114	    @ExceptionHandler(Exception.class)
115	    @ResponseBody
116	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
117	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
118	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
119	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
120	        return ResponseEntity.status(status).body(detail);
121	    }
122	
123	    /**
124	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
125	     * method returns a 404 Not Found status if an entity does not exist.
126	     *
127	     * @param e The {@link DataIntegrityViolationException} to be handled
128	     * @param request {@link HttpServletRequest} object referring to the current request.
129	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
130	     */
131	    @ExceptionHandler(DataIntegrityViolationException.class)
132	    @ResponseBody
133	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
134	        logger.warn("Data integrity violation at {} {}: {}",
135	            request.getMethod(),
136	            request.getRequestURI(),
137	            e.getMessage());
138	        logger.debug("Data integrity violation stacktrace", e);
139	        HttpStatus status = HttpStatus.NOT_FOUND;
140	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
141	        return ResponseEntity.status(status).body(detail);
142	    }
143	
144	    /**
145	     * Handles exception thrown by Bean Validation on controller methods parameters
146	     *
147	     * @param e The {@link MethodArgumentNotValidException} to be handled
148	     * @param request {@link HttpServletRequest} object referring to the current request.
149	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
150	     */
151	    @ExceptionHandler(MethodArgumentNotValidException.class)
152	    @ResponseBody
153	    public ResponseEntity<?> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
154	        HttpStatus status = HttpStatus.BAD_REQUEST;
155	        BindingErrorsResponse errors = new BindingErrorsResponse();
156	        BindingResult bindingResult = e.getBindingResult();
157	        if (bindingResult.getTarget() instanceof OwnerFieldsDto ownerFields) {
158	            List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFields);
159	            if (!missingFields.isEmpty()) {
160	                return ResponseEntity.status(status).body(new ValidationErrorsResponse(missingFields));
161	            }
162	        }
163	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
164	        if (bindingResult.hasErrors()) {
165	            errors.addAllErrors(bindingResult);
166	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
167	                .map(fieldError -> {
168	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
169	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
170	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
171	                        fieldError.getField(),
172	                        defaultMessage,
173	                        rejectedValue);
174	                    return new ValidationMessageDto(message)
175	                        .putAdditionalProperty("field", fieldError.getField())
176	                        .putAdditionalProperty("rejectedValue", rejectedValue)
177	                        .putAdditionalProperty("defaultMessage", defaultMessage);
178	                })
179	                .toList();
180	            logger.debug("Validation error at {} {}: {}",
181	                request.getMethod(),
182	                request.getRequestURI(),
183	                bindingResult.getFieldErrors());
184	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
185	            return ResponseEntity.status(status).body(detail);
186	        }
187	        return ResponseEntity.status(status).body(detail);
188	    }
189	
190	    /**
191	     * Handles {@link MissingOwnerFieldsException} raised when an owner is created with required
192	     * fields that are missing or blank. Returns a 400 Bad Request whose {@code errors} array lists
193	     * the name of each offending field.
194	     *
195	     * @param e The {@link MissingOwnerFieldsException} to be handled
196	     * @return A {@link ResponseEntity} containing the offending field names and a 400 Bad Request status.
197	     */
198	    @ExceptionHandler(MissingOwnerFieldsException.class)
199	    @ResponseBody
200	    public ResponseEntity<ValidationErrorsResponse> handleMissingOwnerFieldsException(MissingOwnerFieldsException e) {
201	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(new ValidationErrorsResponse(e.getFields()));
202	    }
203	
204	    /**
205	     * Handles {@link InvalidTelephoneException} raised when an owner's telephone does not
206	     * reduce to exactly ten digits. Returns a 400 Bad Request whose {@code errors} array
207	     * names the offending field.
208	     *
209	     * @param e The {@link InvalidTelephoneException} to be handled
210	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
211	     */
212	    @ExceptionHandler(InvalidTelephoneException.class)
213	    @ResponseBody
214	    public ResponseEntity<ValidationErrorsResponse> handleInvalidTelephoneException(InvalidTelephoneException e) {
215	        logger.debug("Invalid telephone: {}", e.getMessage());
216	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
217	            .body(new ValidationErrorsResponse(List.of(InvalidTelephoneException.FIELD)));
218	    }
219	
220	    /**
221	     * Handles {@link InvalidEmailException} raised when an owner's email is present but is
222	     * not a syntactically valid address. Returns a 400 Bad Request whose {@code errors}
223	     * array names the offending field.
224	     *
225	     * @param e The {@link InvalidEmailException} to be handled
226	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
227	     */
228	    @ExceptionHandler(InvalidEmailException.class)
229	    @ResponseBody
230	    public ResponseEntity<ValidationErrorsResponse> handleInvalidEmailException(InvalidEmailException e) {
231	        logger.debug("Invalid email: {}", e.getMessage());
232	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
233	            .body(new ValidationErrorsResponse(List.of(InvalidEmailException.FIELD)));
234	    }
235	
236	    /**
237	     * Handles {@link DisposableEmailDomainException} raised when an owner's email domain is on the
238	     * disposable-domain blocklist. Returns a 400 Bad Request whose {@code errors} array names the
239	     * offending field.
240	     *
241	     * @param e The {@link DisposableEmailDomainException} to be handled
242	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
243	     */
244	    @ExceptionHandler(DisposableEmailDomainException.class)
245	    @ResponseBody
246	    public ResponseEntity<ValidationErrorsResponse> handleDisposableEmailDomainException(DisposableEmailDomainException e) {
247	        logger.debug("Disposable email domain: {}", e.getMessage());
248	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
249	            .body(new ValidationErrorsResponse(List.of(DisposableEmailDomainException.FIELD)));
250	    }
251	
252	    /**
253	     * Handles {@link InvalidPostcodeException} raised when an owner's postcode is present but is
254	     * not four digits, or is out of range for the region of the owner's city. Returns a 400 Bad
255	     * Request whose {@code errors} array names the offending field.
256	     *
257	     * @param e The {@link InvalidPostcodeException} to be handled
258	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
259	     */
260	    @ExceptionHandler(InvalidPostcodeException.class)
261	    @ResponseBody
262	    public ResponseEntity<ValidationErrorsResponse> handleInvalidPostcodeException(InvalidPostcodeException e) {
263	        logger.debug("Invalid postcode: {}", e.getMessage());
264	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
265	            .body(new ValidationErrorsResponse(List.of(InvalidPostcodeException.FIELD)));
266	    }
267	
268	    /**
269	     * Handles {@link FutureRegistrationDateException} raised when an owner is created with a
270	     * supplied registration date later than the server's current date. Returns a 400 Bad Request
271	     * whose {@code errors} array names the offending field.
272	     *
273	     * @param e The {@link FutureRegistrationDateException} to be handled
274	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
275	     */
276	    @ExceptionHandler(FutureRegistrationDateException.class)
277	    @ResponseBody
278	    public ResponseEntity<ValidationErrorsResponse> handleFutureRegistrationDateException(FutureRegistrationDateException e) {
279	        logger.debug("Future registration date: {}", e.getMessage());
280	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
281	            .body(new ValidationErrorsResponse(List.of(FutureRegistrationDateException.FIELD)));
282	    }
283	
284	    /**
285	     * Handles {@link DuplicateIdentityException} raised when an owner is created whose whole
286	     * derived identity key already belongs to another owner. This is the single duplicate rule
287	     * that replaces the former separate telephone, email and household checks. Returns a 409
288	     * Conflict whose {@code errors} array names the offending field.
289	     *
290	     * @param e The {@link DuplicateIdentityException} to be handled
291	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
292	     */
293	    @ExceptionHandler(DuplicateIdentityException.class)
294	    @ResponseBody
295	    public ResponseEntity<ValidationErrorsResponse> handleDuplicateIdentityException(DuplicateIdentityException e) {
296	        logger.debug("Duplicate identity: {}", e.getMessage());
297	        return ResponseEntity.status(HttpStatus.CONFLICT)
298	            .body(new ValidationErrorsResponse(List.of(DuplicateIdentityException.FIELD)));
299	    }
300	
301	    /**
302	     * Handles {@link HouseholdDuplicateException} raised when an owner is created into a household
303	     * (same last name and postcode) that already exists without declaring {@code sharesHousehold}.
304	     * Returns a 409 Conflict whose {@code errors} array names the offending field.
305	     *
306	     * @param e The {@link HouseholdDuplicateException} to be handled
307	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
308	     */
309	    @ExceptionHandler(HouseholdDuplicateException.class)
310	    @ResponseBody
311	    public ResponseEntity<ValidationErrorsResponse> handleHouseholdDuplicateException(HouseholdDuplicateException e) {
312	        logger.debug("Household duplicate: {}", e.getMessage());
313	        return ResponseEntity.status(HttpStatus.CONFLICT)
314	            .body(new ValidationErrorsResponse(List.of(HouseholdDuplicateException.FIELD)));
315	    }
316	
317	    /**
318	     * Handles {@link CityOwnerLimitException} raised when an owner is created in a city that
319	     * already contains the maximum allowed number of owners. Returns a 409 Conflict whose
320	     * {@code errors} array names the offending field.
321	     *
322	     * @param e The {@link CityOwnerLimitException} to be handled
323	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
324	     */
325	    @ExceptionHandler(CityOwnerLimitException.class)
326	    @ResponseBody
327	    public ResponseEntity<ValidationErrorsResponse> handleCityOwnerLimitException(CityOwnerLimitException e) {
328	        logger.debug("City owner limit reached: {}", e.getMessage());
329	        return ResponseEntity.status(HttpStatus.CONFLICT)
330	            .body(new ValidationErrorsResponse(List.of(CityOwnerLimitException.FIELD)));
331	    }
332	
333	    /**
334	     * Handles {@link DailyOwnerLimitException} raised when an owner is created on a day that has
335	     * already reached the maximum allowed number of owner registrations. Returns a 429 Too Many
336	     * Requests whose {@code errors} array names the offending field.
337	     *
338	     * @param e The {@link DailyOwnerLimitException} to be handled
339	     * @return A {@link ResponseEntity} containing the offending field name and a 429 status.
340	     */
341	    @ExceptionHandler(DailyOwnerLimitException.class)
342	    @ResponseBody
343	    public ResponseEntity<ValidationErrorsResponse> handleDailyOwnerLimitException(DailyOwnerLimitException e) {
344	        logger.debug("Daily owner limit reached: {}", e.getMessage());
345	        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS)
346	            .body(new ValidationErrorsResponse(List.of(DailyOwnerLimitException.FIELD)));
347	    }
348	
349	}
